const upsertBaselinePolicy = `-- name: UpsertBaselinePolicy :exec
INSERT INTO policies (id, org_id, document, version)
VALUES ($1, NULL, $2, 1)
ON CONFLICT ((org_id IS NULL)) WHERE org_id IS NULL
DO UPDATE SET document = EXCLUDED.document, version = policies.version + 1, updated_at = now()
`

type UpsertBaselinePolicyParams struct {
	ID       uuid.UUID `json:"id"`
	Document []byte    `json:"document"`
}

func (q *Queries) UpsertBaselinePolicy(ctx context.Context, arg UpsertBaselinePolicyParams) error {
	_, err := q.db.Exec(ctx, upsertBaselinePolicy, arg.ID, arg.Document)
	return err
}

